/**
 * ViewTransition primitive (@base-ui/react/button).
 *
 * Platform Reference: Modern Web Guidance (MWG: same-document-transitions)
 *
 * TAXONOMY & USAGE:
 * - Declarative container and trigger components for the View Transitions API (document.startViewTransition).
 * - Enables smooth, GPU-accelerated morphing between states (thumbnail to hero, tab switches, list expansions).
 * - Degrades gracefully on unsupported browsers (feature-detected) by running the state update immediately without errors.
 * - Bypasses the animation under prefers-reduced-motion and offers opt-in focus routing (focusTarget) to prevent screen reader disorientation.
 * - Follows DESIGN.md Tier B interactive controls: concentric radius, 44px minimum hit targets, and floating 2px focus ring.
 */
import * as React from 'react';
import { Button as BaseButton } from '@base-ui/react/button';
import { useViewTransition, type TransitionOptions } from '@/lib/view-transitions';
import { cn } from '@/lib/utils';

export interface ViewTransitionProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Unique view-transition-name CSS identifier for morphing pair */
  name?: string;
  children: React.ReactNode;
  className?: string;
}

/**
 * Container marking an element for shared View Transition morphing.
 */
export const ViewTransition = React.forwardRef<HTMLDivElement, ViewTransitionProps>(
  ({ name, className, style, children, ...props }, ref) => {
    const dynamicStyle: React.CSSProperties = {
      ...style,
      ...(name ? { viewTransitionName: name } : {}),
    };

    return (
      <div
        ref={ref}
        style={dynamicStyle}
        className={cn('inline-block', className)}
        {...props}
      >
        {children}
      </div>
    );
  }
);
ViewTransition.displayName = 'ViewTransition';

export interface ViewTransitionTriggerProps
  extends React.ComponentPropsWithoutRef<typeof BaseButton> {
  /** The state update callback to execute within document.startViewTransition */
  onTransition?: () => void | Promise<void>;
  /** Optional focus routing options once the transition completes */
  transitionOptions?: TransitionOptions;
  children: React.ReactNode;
  className?: string;
}

/**
 * Interactive button executing updates inside a View Transition.
 */
export const ViewTransitionTrigger = React.forwardRef<HTMLButtonElement, ViewTransitionTriggerProps>(
  (
    {
      onTransition,
      transitionOptions,
      onClick,
      disabled,
      className,
      children,
      ...props
    },
    ref
  ) => {
    const { startTransition, isTransitioning } = useViewTransition();

    const handleClick: React.ComponentPropsWithoutRef<typeof BaseButton>['onClick'] = (e) => {
      onClick?.(e);
      if (onTransition && !e.defaultPrevented) {
        startTransition(onTransition, transitionOptions).catch((error) => {
          console.error('View transition update failed:', error);
        });
      }
    };

    return (
      <BaseButton
        ref={ref}
        {...props}
        onClick={handleClick}
        disabled={disabled || isTransitioning}
        focusableWhenDisabled
        aria-busy={isTransitioning || undefined}
        className={cn(
          'inline-flex items-center justify-center min-h-[44px] min-w-[44px] rounded-md font-label text-sm font-semibold transition-colors cursor-pointer select-none',
          'focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-primary',
          className
        )}
      >
        {children}
      </BaseButton>
    );
  }
);
ViewTransitionTrigger.displayName = 'ViewTransitionTrigger';

export { useViewTransition };

export default ViewTransition;

/**
 * View Transitions API React hook and utility.
 *
 * Platform Reference: Modern Web Guidance (MWG: same-document-transitions)
 *
 * Provides a strongly typed wrapper around document.startViewTransition()
 * with progressive enhancement fallback, reduced motion bypass, and
 * opt-in accessibility focus routing (via the focusTarget option).
 */
import * as React from 'react';
import { flushSync } from 'react-dom';

interface ViewTransition {
  ready: Promise<void>;
  finished: Promise<void>;
  updateCallbackDone: Promise<void>;
  skipTransition(): void;
}

declare global {
  interface Document {
    startViewTransition(updateCallback?: () => Promise<void> | void): ViewTransition;
  }
}

export interface TransitionOptions {
  /** Element or ref to programmatically focus once the transition completes (MWG accessibility routing) */
  focusTarget?: HTMLElement | React.RefObject<HTMLElement | null> | null;
  /** Temporary view-transition-name to apply to targetElement during morphing */
  transitionName?: string;
  /** Element on which to temporarily set transitionName */
  targetElement?: HTMLElement | null;
}

export interface UseViewTransitionReturn {
  /** Whether the current browser supports the View Transitions API */
  isSupported: boolean;
  /** Whether a view transition is currently in progress */
  isTransitioning: boolean;
  /** Executes an asynchronous or synchronous DOM/state update inside a View Transition */
  startTransition: (
    updateFn: () => void | Promise<void>,
    options?: TransitionOptions
  ) => Promise<void>;
}

export function useViewTransition(): UseViewTransitionReturn {
  const [isTransitioning, setIsTransitioning] = React.useState(false);

  const isSupported = React.useMemo(() => {
    return (
      typeof document !== 'undefined' &&
      typeof document.startViewTransition === 'function'
    );
  }, []);

  const startTransition = React.useCallback(
    async (
      updateFn: () => void | Promise<void>,
      options?: TransitionOptions
    ): Promise<void> => {
      const { focusTarget, transitionName, targetElement } = options || {};

      // Preserve any existing inline name so it can be restored afterwards
      const previousName =
        transitionName && targetElement
          ? targetElement.style.getPropertyValue('view-transition-name')
          : '';
      if (transitionName && targetElement) {
        targetElement.style.setProperty('view-transition-name', transitionName);
      }

      const routeFocus = () => {
        if (!focusTarget) return;
        const resolved =
          'current' in focusTarget ? focusTarget.current : focusTarget;
        if (resolved) {
          // Only make natively non-focusable targets programmatically focusable, and undo it on blur
          if (resolved.tabIndex < 0 && !resolved.hasAttribute('tabindex')) {
            resolved.setAttribute('tabindex', '-1');
            resolved.addEventListener('blur', () => resolved.removeAttribute('tabindex'), { once: true });
          }
          resolved.focus({ preventScroll: true });
        }
      };

      const cleanupName = () => {
        if (transitionName && targetElement) {
          if (previousName) {
            targetElement.style.setProperty('view-transition-name', previousName);
          } else {
            targetElement.style.removeProperty('view-transition-name');
          }
        }
      };

      // Commit React state updates synchronously so the new DOM is captured
      const runUpdate = async () => {
        let result: void | Promise<void> = undefined;
        flushSync(() => {
          result = updateFn();
        });
        await result;
      };

      const prefersReducedMotion =
        typeof window !== 'undefined' &&
        typeof window.matchMedia === 'function' &&
        window.matchMedia('(prefers-reduced-motion: reduce)').matches;

      // Fallback for browsers without View Transitions support
      if (!isSupported || !document.startViewTransition || prefersReducedMotion) {
        try {
          await updateFn();
          routeFocus();
        } finally {
          cleanupName();
        }
        return;
      }

      setIsTransitioning(true);

      try {
        const transition = document.startViewTransition(runUpdate);
        transition.ready.catch(() => {});

        // Rejects if the update callback throws, so failures reach the caller
        await transition.finished;
        routeFocus();
      } catch (err: unknown) {
        // A skipped transition is not a failure; any other error propagates
        if (!(err instanceof DOMException && err.name === 'AbortError')) {
          throw err;
        }
      } finally {
        cleanupName();
        setIsTransitioning(false);
      }
    },
    [isSupported]
  );

  return {
    isSupported,
    isTransitioning,
    startTransition,
  };
}

export default useViewTransition;
